/** @file React qr code view; authorization and authoritative state remain on the server. */
import { useI18n } from '../i18n/I18nProvider.jsx';
import { useMemo } from 'react';
import { qrSvg } from '../lib/qr.js';
export default function QrCode({ value, label = 'Scannable boarding metadata QR code' }) {
  const { t, locale } = useI18n();
  const svg = useMemo(() => {
    try {
      return qrSvg(value);
    } catch {
      return null;
    }
  }, [value]);
  // Markup is generated by the bundled QR library; no user HTML is interpolated.
  return svg ? (
    <div
      className="qr"
      role="img"
      aria-label={t(label)}
      dangerouslySetInnerHTML={{
        __html: svg,
      }}
    />
  ) : (
    <p className="error">{t('QR generation failed. Your booking reference is still available.')}</p>
  );
}
